/* 리프레시 토큰 해시 갱신 */
UPDATE RFRSH_TKN
   SET RFRSH_TKN_HASH = #{rfrshTknHash}
     , MDFCN_DT = NOW()
 WHERE RFRSH_TKN_SN = #{rfrshTknSn}

/* 리프레시 토큰 폐기 */
UPDATE RFRSH_TKN
   SET DSCD_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE RFRSH_TKN_SN = #{rfrshTknSn}
   AND DSCD_DT IS NULL

/* 해시로 리프레시 토큰 폐기 */
UPDATE RFRSH_TKN
   SET DSCD_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE RFRSH_TKN_HASH = #{rfrshTknHash}
   AND DSCD_DT IS NULL
